"""UTF-8 JSON Lines persistence."""

import json
import re
from datetime import datetime
from pathlib import Path


_FIELDS = {"id", "account", "amount_cents", "timestamp"}
_RFC3339_UTC = re.compile(
    r"\A[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?Z\Z"
)


def _validate_event(event):
    if not isinstance(event, dict) or set(event) != _FIELDS:
        raise ValueError("event must contain exactly id, account, amount_cents, and timestamp")
    result = dict(event)
    for field in ("id", "account"):
        value = result[field]
        if not isinstance(value, str) or not value.strip():
            raise ValueError("{} must be a nonempty string".format(field))
        result[field] = value.strip()
    amount = result["amount_cents"]
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError("amount_cents must be an integer")
    timestamp = result["timestamp"]
    if not isinstance(timestamp, str) or not _RFC3339_UTC.fullmatch(timestamp):
        raise ValueError("timestamp must be a valid RFC3339 UTC instant ending in Z")
    try:
        datetime.fromisoformat(timestamp[:-1] + "+00:00")
    except ValueError as exc:
        raise ValueError("timestamp must be a valid RFC3339 UTC instant ending in Z") from exc
    result["timestamp"] = timestamp
    return result


def read_events(path):
    """Read and validate events from a UTF-8 JSON Lines ledger."""
    ledger = Path(path)
    if not ledger.exists():
        return []
    events = []
    by_id = {}
    try:
        with ledger.open("r", encoding="utf-8") as stream:
            for line_number, line in enumerate(stream, 1):
                if not line.strip():
                    raise ValueError("blank JSON Lines record at line {}".format(line_number))
                try:
                    event = json.loads(line)
                except (json.JSONDecodeError, UnicodeDecodeError) as exc:
                    raise ValueError("invalid JSON at line {}".format(line_number)) from exc
                try:
                    event = _validate_event(event)
                except ValueError as exc:
                    raise ValueError("invalid event at line {}: {}".format(line_number, exc)) from exc
                previous = by_id.get(event["id"])
                if previous is not None and previous != event:
                    raise ValueError("event ID already exists with different payload")
                by_id[event["id"]] = event
                events.append(event)
    except UnicodeDecodeError as exc:
        raise ValueError("ledger is not valid UTF-8") from exc
    return events


def write_events(path, events):
    """Validate and replace the ledger with UTF-8 JSON Lines records."""
    records = [_validate_event(event) for event in events]
    ledger = Path(path)
    ledger.parent.mkdir(parents=True, exist_ok=True)
    with ledger.open("w", encoding="utf-8", newline="\n") as stream:
        for event in records:
            stream.write(json.dumps(event, ensure_ascii=False, separators=(",", ":")))
            stream.write("\n")

