from ledger.storage import _validate_event, write_events, read_events
from pathlib import Path
import tempfile
base = dict(id='x', account='a', amount_cents=1)
for ts in ('2026-02-30T12:00:00Z', '2026-10-01T12:00:00+00:00', ' 2026-10-01T12:00:00Z', '2026-10-01T12:00:00Z '):
    try:
        _validate_event(dict(base, timestamp=ts))
    except ValueError:
        pass
    else:
        raise AssertionError(ts)
assert _validate_event(dict(base, timestamp='2026-10-01T12:00:00.123Z'))['timestamp'] == '2026-10-01T12:00:00.123Z'
with tempfile.TemporaryDirectory() as d:
    p = Path(d) / 'ledger.jsonl'
    p.write_text('{"id":"x","account":"a","amount_cents":1,"timestamp":"2026-02-30T12:00:00Z"}\n', encoding='utf-8')
    try:
        read_events(p)
    except ValueError:
        pass
    else:
        raise AssertionError('read accepted invalid stored record')
    p.write_text('preserve', encoding='utf-8')
    try:
        write_events(p, [dict(base, timestamp='2026-02-30T12:00:00Z')])
    except ValueError:
        pass
    else:
        raise AssertionError('write accepted invalid timestamp')
    assert p.read_text(encoding='utf-8') == 'preserve'
print('timestamp validation checks passed')
